-- Final foundation integrity: target/reply validation and lifecycle invariants.
alter table public.messages add column if not exists reply_to uuid references public.messages(id) on delete set null;
create or replace function public.validate_message_reply() returns trigger language plpgsql security definer set search_path=public as $$ declare parent messages%rowtype; begin if new.reply_to is null then return new; end if; select * into parent from messages where id=new.reply_to; if not found or parent.deleted_at is not null or parent.room_id is distinct from new.room_id or parent.thread_id is distinct from new.thread_id then raise exception 'Reply must target a visible message in the same conversation'; end if; return new; end $$;
drop trigger if exists validate_message_reply_trigger on messages; create trigger validate_message_reply_trigger before insert or update of reply_to,room_id,thread_id on messages for each row execute procedure validate_message_reply();
create or replace function public.create_room(room_name text, room_topic text, private_room boolean) returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid; base_slug text; candidate text; suffix integer:=1; begin perform require_authenticated(); if char_length(trim(room_name)) not between 3 and 60 or char_length(coalesce(room_topic,''))>240 then raise exception 'Invalid room details'; end if; base_slug:=trim(both '-' from regexp_replace(lower(trim(room_name)),'[^a-z0-9]+','-','g')); if base_slug='' then raise exception 'Invalid room name'; end if; candidate:=base_slug; while exists(select 1 from rooms where slug=candidate) loop suffix:=suffix+1; candidate:=base_slug||'-'||suffix; end loop; insert into rooms(slug,name,topic,kind,is_private,created_by) values(candidate,trim(room_name),nullif(trim(room_topic),''),'custom',private_room,auth.uid()) returning id into new_id; insert into room_members(room_id,user_id,role) values(new_id,auth.uid(),'owner'); return new_id; end $$;
